// JavaScript's lever is shape stability, not an inline keyword.
// Two objects built the SAME way share a hidden class -> monomorphic -> inlined.
function makeA(x) { return { x: x, y: 0 }; }   // {x, y} in that order
function makeB(x) { return { y: 0, x: x }; }   // {y, x} -> a DIFFERENT hidden class

// A call site that sees both is polymorphic; three or more is megamorphic and
// defeats the inline cache - which is the cliff that matters, not call overhead.
function hot(o) { return o.x + o.y; }

